def intervalPuncturedCutoff (r : ℝ) (n : ℕ) (t : UnitInterval) : C(UnitInterval, ℝ) :=
  ⟨fun x => min 1 ((n + 1 : ℝ) * dist t x) *
    min 1 ((n + 1 : ℝ) * max 0 (r - dist t x)), by fun_prop⟩

